INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1154000-gs321', 'stk-s_h_a_d_o_w', 'GS 321', 'info', '{"desc": "أولا أشكر الي جابوا على الاسئلة لأنها ساعدتني في اختصار الوقت\n\nلكن للأسف في بعض الأقسام زي الـ Social Psychology و الـ Personality الحلول مختصرة جدا و غير كافية للاستعداد للاختبار النهائي\n\nبعد ما اختبرت اليوم لقيت ان الستدي قايد غطى حوالي نص الاختبار بس بسبب اختصار الحلول\n\nأنصح الطلاب للأترام الجاية انهم يحلو الأسئلة بنفسهم من الكتاب مباشرة و مع الاستفادة من حل الشباب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/f-exam-gs321-study-guide/126488/14", "user": "S_H_A_D_O_W", "ts": 1357224679000, "tid": 126488, "pn": 14}}', 1357224679000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p262586-gs321', 'stk-user82', 'GS 321', 'info', '{"desc": "ايش دخل الدكتور / العصيل في مادة ( مبادئ السلوك الإنساني ) Gs 321 !!\n\nالدكتور العصيل يدرس مادة ( العلاقات الدولية ) Gs 423 و هو - كما ذكر الإخوان - مدرس جيد ، و متمكن من المادة و له خبرة طويلة جدا في هذا المجال .\n\nأما مادة ( مبادئ السلوك الإنساني ) Gs 321 … فسوف يدرسها 4 من أعضاء هيئة التدريس :\n\n2 منهم يعملون ( أساسا ) مع التطوير الأكاديمي Dad و هم د / ضيف الله المطرودي و د / عيد الحربي\n\nو 2 منهم يعملون ( أساسا ) كاستشاريين نفسيين مع مركز التوجيه و الإرشاد و هم د / علي مفتاح و د / هشام خوجلي .\n\nو الحقيقة ليست عندي أي خلفية عن هؤلاء … جميعا … من ناحية الشرح و الاختبارات و الدرجات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-321-instructors/62876/4", "user": "user82", "ts": 1209584704000, "tid": 62876, "pn": 4}}', 1209584704000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1225981-gs321', 'stk-ahmad18', 'GS 321', 'info', '{"desc": "سلام عليكم …\n\nانا اخذت المادة في ترم 111\n\nوالفاينل جااا من الستدي قاااااااايد بالضبببببط …\n\nالحمد لله … حليناه انا والشباب في المنتدى هنا …\n\nوفيه ملف وورد موجود في قسم الدراسات العامة بالحلول…\n\nالاسئلة كانت تقريبا 30 سؤال …\n\nحليت انا وخووي تقريبا 15 سؤال منها واخذت منا 3 ايام كاملات والباقي اخذناه من الشباب هنا وجمعناه في ملف واحد … وعارفين لغة الكتاب صعبة كيف !!\n\nعالعموم اذا ما ودكم تدورون …\n\nروحو google واكتب ( gs321 study guide حلول )\n\nاو بعض من جمل البحث هذي …\n\nبتلاقوون موضوع فيه الحلووووول كاملة …\n\nلو صميت الحلول كلها بتجيب ان شاء الله عالاقل 27 من 30\n\nلا تنسون من دعواتكم ياشباب …\n\n=)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs321-dr-christopher-garris/144759/6", "user": "Ahmad18", "ts": 1369223169000, "tid": 144759, "pn": 6}}', 1369223169000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p315672-gs321', 'stk-abdullah266', 'GS 321', 'info', '{"desc": "ماعندي اي معلومة عن الكورس الي تسأل عنه… بس انا أخذت في ترم 071 GS 221\n\" Industrial Soc & Prod\"\nصراحة كانت مادة سهلة … معلومات عامة… بس اسمع للدكتورخضير… بعدين أحفظ السلايدات واختبر… وماكان فيه بحث… بس المفترض كان فيه الالقاء بس لغاه الله يخليه الدكتور خضير لانه كان مشغول ومو فاضي…\nنزل عنده ترا فلة والحصة وناسة ويغيب كثير…\n\nوبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs321/66575/2", "user": "Abdullah266", "ts": 1223417527000, "tid": 66575, "pn": 2}}', 1223417527000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p771015-gs321', 'stk-user2352', 'GS 321', 'srcU', '{"html": "تفضل هذا الـguidelines اللي أعطانا اياه الدكتور كريستيوفر جاريس وبالتوفيق<br><br>​<span data-fid=\"stk-f771015-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f771015-0": {"name": "study guide.zip", "v": "data:application/zip;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-321/101235/5", "user": "user2352", "ts": 1295810584000, "tid": 101235, "pn": 5}}', 1295810584000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1039886-gs321', 'stk-mohammy', 'GS 321', 'srcU', '{"html": "يا شباب شكلكم مضيعين. انا منزل مع جارس و عطانا ورقة فيها اسألة و الإختبار مب يجي الا منها حسب كلامه. الاسألة تقدرون تقولون شاملة لمتيريال الإختبار بس تخليك تعرف شتذاكر بالضبط.<br><br>هذي الأسألة:<br><br>Health Psychology<br><br>What is stress? What causes it?<br><br>Describe the three categories of stressors (including examples).<br><br>Can stress be beneficial? Explain.<br><br>What are the different categories of coping strategies? Which strategies are ineffective, and why?<br><br>Describe the effect of personality and stress on heart disease.<br><br>What predicts happiness/well-being? What doesn’t?<br><br>Define and explain the General Adaptation Syndrome.<br><br>Social Psychology<br><br>Explain the impression formation process. What role do schemas play?<br><br>What are the two main types of attributions? State and explain the two main errors in attribution.<br><br>What are the main compliance techniques described in the book? Why are they effective?<br><br>Know and be able to differentiate between stereotypes, prejudice, and discrimination.<br><br>What factors contribute to attraction/liking? How?<br><br>What are the three components to consider in persuasion? What role does processing play?<br><br>Compare and contrast the three main types of Social Influence.<br><br>When does aggression and helping behavior occur?<br><br>Thinking<br><br>What are schemas and prototypes? How do we use them?<br><br>Distinguish between Algorithms and Heuristics and know when each are used.<br><br>What is fixedness and what role does it play in problem solving?<br><br>How is creativity important (including its relation to convergent and divergent thinking) in problem solving?<br><br>What is the process of problem solving? What problems can occur? What be helpful?<br><br>What are the different approaches to intelligence? Compare the traditional, single-factor approach to intelligence to newer approaches.<br><br>How is intelligence measured? How do the tests differ?<br><br>Personality<br><br>What is personality? What effect does it have on behavior and thinking?<br><br>Describe the main approaches to personality and identify the strengths and weakness of each.<br><br>List and describe the Big Five personality traits.<br><br>What’s the difference between self-esteem and self-efficacy?<br><br>List and describe the three main components of personality, according to Freud. How do they interact?<br><br>What are defense mechanisms? Why/when are they used?<br><br>Describe the main methods of assessing personality?<br><br>Memory<br><br>What are encoding, storage, and retrieval? How do they work together?<br><br>Describe the three types/stages of memory (including their limitations) and describe how they interact.<br><br>What role does encoding play in the memory process? How does chunking and repetition aid the encoding process?<br><br>What are the different kinds of retrieval and how do they work? Why might retrieval fail?<br><br>What are explicit and implicit memory? How do they differ?<br><br>What are the different types of forgetting? When do they occur?<br><br>​<span data-fid=\"stk-f1039886-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1039886-0": {"name": "Study Guide.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/77ad35956171c67cbbd1f421462db014a88e3759c3fb146de4144fa8db5b9d24"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-321/125613/7", "user": "Mohammy", "ts": 1337439174000, "tid": 125613, "pn": 7}}', 1337439174000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
